344	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
345	{
346	  uint32_t apb_id1;
347	  uint32_t apb_id2;
348	
349	  ephy_led_pinmux();
350	
351	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
352	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
353	   * This ONLY releases resets and programs the PHY ID — it does NOT
354	   * run the full analog tuning sequence.  The full tuning (which
355	   * accesses internal pages and starts auto-negotiation) must run
356	   * AFTER the MDIO interface is confirmed operational, just as
357	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
358	   */
359	
360	  /* Select APB interface to access EPHY registers */
361	
362	  putreg32(0x0001, phy_top + 0x4);
363	
364	  /* Release shutdown */
365	
366	  putreg32(0x0900, phy_top);
367	
368	  /* Release dig_rst_n — enables MII register access via APB */
369	
370	  putreg32(0x0904, phy_top);
371	
372	  /* Switch to Page 5 for ANA init */
373	
374	  putreg32(0x0500, phy_base + 0x7c);
375	
376	  /* ANA_PD (power-down release) */
377	
378	  putreg32(0x0c00, phy_base + 0x40);
379	
380	  /* ANA_EN */
381	
382	  putreg32(0x0c7e, phy_base + 0x40);
383	  up_mdelay(1);
384	
385	  /* Release ana_rst_n */
386	
387	  putreg32(0x0906, phy_top);
388	  putreg32(0x0500, phy_base + 0x7c);
389	
390	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
391	
392	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
393	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
394	
395	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
396	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
397	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
398	         "%04" PRIX32 "\n", apb_id1, apb_id2);
399	
400	  /* Switch control to MDIO (GMAC) so the DWMAC1000 MDIO controller can
401	   * discover and communicate with the PHY.
402	   */
403	
404	  putreg32(0x0000, phy_top + 0x4);
405	  up_mdelay(10);
406	
407	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
408	         " sel=0x%08" PRIX32 "\n",
409	         getreg32(phy_top), getreg32(phy_top + 0x4));
410	}
