656	/****************************************************************************
657	 * Private Functions - DMA Descriptor Management
658	 ****************************************************************************/
659	
660	static int alloc_dma(struct sg2000_eth_priv_s *priv)
661	{
662	  int i;
663	
664	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
665	                                sizeof(struct sg2000_dma_desc_s));
666	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
667	                                sizeof(struct sg2000_dma_desc_s));
668	
669	  if (!priv->tx_desc || !priv->rx_desc)
670	    {
671	      return -ENOMEM;
672	    }
673	
674	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
676	
677	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
678	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
679	   */
680	
681	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
682	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
683	
684	  for (i = 0; i < TX_RING_SIZE; i++)
685	    {
686	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
687	      if (!priv->tx_buf[i])
688	        {
689	          return -ENOMEM;
690	        }
691	
692	      priv->tx_pkt[i] = NULL;
693	    }
694	
695	  for (i = 0; i < RX_RING_SIZE; i++)
696	    {
697	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
698	      if (!priv->rx_buf[i])
699	        {
700	          return -ENOMEM;
701	        }
702	    }
703	
704	  return 0;
705	}
706	
707	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
708	{
709	  uintptr_t base = priv->gmac_base;
710	  int i;
711	
712	  /* Initialize TX descriptors.
713	   * Mark the last descriptor with END_RING so DMA knows the ring boundary.
714	   */
715	
716	  for (i = 0; i < TX_RING_SIZE; i++)
717	    {
718	      priv->tx_desc[i].des0 = 0;
719	      priv->tx_desc[i].des1 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
720	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
721	      priv->tx_desc[i].des3 = 0;
722	      priv->tx_pkt[i] = NULL;
723	    }
724	
725	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
726	   * Mark the last descriptor with RER (RX End of Ring) in des1.
727	   */
728	
729	  for (i = 0; i < RX_RING_SIZE; i++)
730	    {
731	      priv->rx_desc[i].des0 = DESC_OWN;
732	      priv->rx_desc[i].des1 = RX_BUF_SIZE |
733	                              ((i == RX_RING_SIZE - 1) ? RX_DESC_RER : 0);
734	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
735	      priv->rx_desc[i].des3 = 0;
736	    }
737	
738	  priv->tx_cur = 0;
739	  priv->tx_dirty = 0;
740	  priv->rx_cur = 0;
741	
742	  /* Verify descriptor size compatibility before configuring DMA Bus Mode.
743	   *
744	   * ATDS=0 uses normal 16-byte descriptors (OWN in TDES0, control bits
745	   * FS/LS/IC/TER in TDES1).  The descriptor size is always 16 bytes
746	   * regardless of the timestamp engine state, so the 32-byte extended
747	   * descriptor problem does not apply here.
748	   *
749	   * We still log HW_FEATURE for diagnostics and explicitly disable the
750	   * timestamp engine if present (timestamp is not used by this driver).
751	   */
752	  {
753	    uint32_t hw_feat = getreg32(base + DMA_HW_FEATURE);
754	
755	    syslog(LOG_INFO,
756	           "sg2000_eth: DMA_HW_FEATURE=0x%08" PRIX32 "\n", hw_feat);
757	
758	    if (hw_feat & DMA_HW_FEATURE_TSEN)
759	      {
760	        /* Timestamp engine is present — not needed, keep it off. */
761	
762	        uint32_t ts_ctrl = getreg32(base + GMAC_TIMESTAMP_CTRL);
763	
764	        if (ts_ctrl & GMAC_TS_TSENA)
765	          {
766	            putreg32(ts_ctrl & ~GMAC_TS_TSENA,
767	                     base + GMAC_TIMESTAMP_CTRL);
768	            syslog(LOG_WARNING,
769	                   "sg2000_eth: timestamp was enabled; "
770	                   "disabled (not used)\n");
771	          }
772	
773	        syslog(LOG_INFO,
774	               "sg2000_eth: timestamp HW present, TSENA=0, "
775	               "ATDS=0 (16-byte normal desc)\n");
776	      }
777	    else
778	      {
779	        syslog(LOG_INFO,
780	               "sg2000_eth: no timestamp HW, "
781	               "ATDS=0 (16-byte normal desc)\n");
782	      }
783	  }
784	
785	  /* Configure DMA Bus Mode (CSR0): Fixed Burst, AAL, USP, PBL=8 (ATDS=0) */
786	  putreg32(DMA_BUS_DEFAULT, base + DMA_BUS_MODE);
787	
788	  /* Configure AXI Bus Mode (CSR10): burst lengths + OSR limits */
789	  putreg32(DMA_AXI_DEFAULT, base + DMA_AXI_BUS_MODE);
790	
791	  /* Write descriptor ring base addresses */
792	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
793	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
794	
795	  /* Mask all DMA interrupts via CSR7 (they are unmasked in start_mac_and_dma) */
796	  putreg32(0, base + DMA_INTR_ENA);
797	}
