799	/****************************************************************************
800	 * Private Functions - MAC and DMA Control
801	 ****************************************************************************/
802	
803	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
804	{
805	  uint32_t hi;
806	  uint32_t lo;
807	
808	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
809	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
810	
811	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
812	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
813	}
814	
815	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
816	{
817	  uintptr_t gmac_base = priv->gmac_base;
818	  uint32_t v;
819	
820	  /* Configure MAC based on PHY negotiation results */
821	
822	  v = GMAC_CORE_INIT;
823	  if (priv->speed == 100)
824	    {
825	      v |= GMAC_CONFIG_FES;   /* 100M */
826	    }
827	
828	  if (priv->duplex)
829	    {
830	      v |= GMAC_CONFIG_DM;    /* Full duplex */
831	    }
832	
833	  /* Enable MAC TX and RX */
834	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
835	
836	  putreg32(v, gmac_base + GMAC_CONFIG);
837	
838	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
839	   * Pass multicast + broadcast + unicast (promiscuous mode).
840	   */
841	
842	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
843	           gmac_base + GMAC_FRAME_FILTER);
844	
845	  /* Enable MAC interrupts */
846	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
847	
848	  /* Enable DMA interrupts via CSR7 */
849	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
850	
851	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
852	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
853	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
854	   */
855	
856	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
857	           DMA_CONTROL_ST | DMA_CONTROL_SR,
858	           gmac_base + DMA_CONTROL);
859	}
860	
861	/****************************************************************************
862	 * Private Functions - Doorbell Helpers
863	 ****************************************************************************/
864	
865	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
866	{
867	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
868	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
869	   */
870	
871	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
872	}
873	
874	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
875	{
876	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
877	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
878	   */
879	
880	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
881	}
