883	/****************************************************************************
884	 * Private Functions - Hardware Transmit
885	 ****************************************************************************/
886	
887	static int hw_transmit(struct sg2000_eth_priv_s *priv,
888	                       const uint8_t *data, int len)
889	{
890	  unsigned int idx = priv->tx_cur;
891	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
892	  irqstate_t flags;
893	  uint32_t csr5_before;
894	  uint32_t csr6;
895	
896	  /* Check if the ring is full */
897	
898	  if (desc->des0 & DESC_OWN)
899	    {
900	      return -EBUSY;
901	    }
902	
903	  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */
904	
905	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
906	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
907	
908	  /* Copy data to DMA TX buffer */
909	
910	  memcpy(priv->tx_buf[idx], data, len);
911	
912	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
913	
914	  /* Set OWN on des0.  FS | LS | IC | len on des1.
915	   * Preserve TER (END_RING) bit in des1 if it was set during init.
916	   */
917	
918	  desc->des1 = (uint32_t)len | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
919	               (desc->des1 & TX_DESC_TER);
920	  desc->des0 = DESC_OWN;
921	
922	  /* Diagnostic: dump first 50 bytes of TX buffer (pointed to by des2).
923	   * Note: des1 is a control/status field (len | FS | LS | IC | TER),
924	   * NOT a buffer pointer.  The actual data buffer address is in des2.
925	   */
926	
927	  {
928	    int i;
929	    int dump_len = len < 50 ? len : 50;
930	
931	    syslog(LOG_INFO,
932	           "sg2000_eth: TX data[%u] des2=0x%08" PRIX32
933	           " first %d bytes:",
934	           idx, desc->des2, dump_len);
935	
936	    for (i = 0; i < dump_len; i += 16)
937	      {
938	        int row = 0;
939	        char hex[64];
940	        char ascii[20];
941	        int j;
942	
943	        row += snprintf(hex + row, sizeof(hex) - row, "  %04x:", i);
944	
945	        for (j = 0; j < 16; j++)
946	          {
947	            if (i + j < dump_len)
948	              {
949	                row += snprintf(hex + row, sizeof(hex) - row,
950	                                " %02x", priv->tx_buf[idx][i + j]);
951	                ascii[j] = (priv->tx_buf[idx][i + j] >= 32 &&
952	                           priv->tx_buf[idx][i + j] < 127)
953	                           ? priv->tx_buf[idx][i + j] : '.';
954	              }
955	            else
956	              {
957	                row += snprintf(hex + row, sizeof(hex) - row, "   ");
958	                ascii[j] = ' ';
959	              }
960	          }
961	
962	        ascii[16] = '\0';
963	        syslog(LOG_INFO, "%s  |%s|\n", hex, ascii);
964	      }
965	  }
966	
967	  /* Diagnostic: dump TX descriptor and DMA state before doorbell */
968	
969	  syslog(LOG_INFO,
970	         "sg2000_eth: TX idx=%u len=%d\n"
971	         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
972	         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
973	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
974	         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
975	         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
976	         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
977	         idx, len,
978	         desc->des0, desc->des1, desc->des2, desc->des3,
979	         csr5_before, csr6,
980	         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
981	         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
982	         data[0], data[1], data[2], data[3], data[4], data[5],
983	         data[6], data[7], data[8], data[9], data[10], data[11],
984	         data[12], data[13]);
985	
986	  flags = up_irq_save();
987	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
988	
989	  /* Memory barrier: ensure descriptor is visible to DMA engine */
990	
991	  __asm__ volatile ("fence w,w" ::: "memory");
992	
993	  tx_doorbell(priv);
994	
995	  /* Verify DMA operation: poll descriptor OWN bit with timeout.
996	   * If DMA clears OWN, TX is working.  If OWN stays set, DMA is stuck.
997	   */
998	
999	  {
1000	    int timeout = 10000;
1001	    while ((desc->des0 & DESC_OWN) && --timeout > 0)
1002	      {
1003	        up_udelay(10);
1004	      }
1005	
1006	    syslog(LOG_INFO,
1007	           "sg2000_eth: TX complete check: OWN=%s timeout=%d "
1008	           "CSR5=0x%08" PRIX32 "\n",
1009	           (desc->des0 & DESC_OWN) ? "STILL_SET(DMA_STUCK)" : "CLEARED(OK)",
1010	           10000 - timeout,
1011	           getreg32(priv->gmac_base + DMA_STATUS));
1012	  }
1013	
1014	  up_irq_restore(flags);
1015	
1016	  return 0;
1017	}
1018	
1019	/****************************************************************************
1020	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1021	 ****************************************************************************/
1022	
1023	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1024	{
1025	  irqstate_t flags = up_irq_save();
1026	
1027	  while (priv->tx_dirty != priv->tx_cur)
1028	    {
1029	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1030	
1031	      if (desc->des0 & DESC_OWN)
1032	        {
1033	          /* Still owned by DMA, stop */
1034	
1035	          break;
1036	        }
1037	
1038	      /* Free the netpkt if we have one tracked for this slot */
1039	
1040	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1041	        {
1042	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1043	          priv->tx_pkt[priv->tx_dirty] = NULL;
1044	
1045	          /* Notify upper half that TX is done */
1046	
1047	          netdev_lower_txdone(&priv->dev);
1048	        }
1049	
1050	      /* Move to next descriptor */
1051	
1052	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1053	    }
1054	
1055	  up_irq_restore(flags);
1056	}
1057	
1058	/****************************************************************************
1059	 * Private Functions - ISR
1060	 ****************************************************************************/
1061	
1062	static int sg2000_eth_isr(int irq, void *context, void *arg)
1063	{
1064	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1065	  uintptr_t base = priv->gmac_base;
1066	  uint32_t status;
1067	  uint32_t mac;
1068	
1069	  /* Clear MAC interrupts */
1070	
1071	  mac = getreg32(base + GMAC_INT_STATUS);
1072	  if (mac)
1073	    {
1074	      putreg32(mac, base + GMAC_INT_STATUS);
1075	    }
1076	
1077	  /* Read DMA Status (CSR5 at 0x1014) */
1078	
1079	  status = getreg32(base + DMA_STATUS);
1080	
1081	  if (!status)
1082	    {
1083	      return OK;
1084	    }
1085	
1086	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
1087	
1088	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1089	
1090	  if (status & DMA_STATUS_NIS)
1091	    {
1092	      /* Normal interrupt */
1093	
1094	      if (status & DMA_STATUS_RI)
1095	        {
1096	          /* RX complete: notify upper half */
1097	          netdev_lower_rxready(&priv->dev);
1098	        }
1099	
1100	      if (status & DMA_STATUS_TI)
1101	        {
1102	          /* TX complete: cleanup descriptors */
1103	          tx_cleanup(priv);
1104	        }
1105	    }
1106	
1107	  if (status & DMA_STATUS_AIS)
1108	    {
1109	      /* Abnormal interrupt - handled silently in ISR context */
1110	    }
1111	
1112	  return OK;
1113	}
