1115	/****************************************************************************
1116	 * Name: sg2000_eth_tx_test
1117	 *
1118	 * Description:
1119	 *   Minimal hardware TX verification test.
1120	 *   Bypasses the network stack — directly programs a TX descriptor,
1121	 *   rings the doorbell, and verifies the DMA engine can:
1122	 *     Layer 1: Fetch the descriptor from DDR  (OWN bit cleared)
1123	 *     Layer 2: Read buffer data correctly     (no Underflow)
1124	 *     Layer 3: Generate TX Complete interrupt  (CSR5 TI bit)
1125	 *
1126	 *   Prerequisite: ifup has completed (PHY up, DMA running).
1127	 *
1128	 ****************************************************************************/
1129	
1130	static int sg2000_eth_tx_test(void)
1131	{
1132	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1133	  unsigned int idx = priv->tx_cur;
1134	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1135	  uint32_t csr5_before;
1136	  uint32_t csr5_after;
1137	  uint32_t csr6;
1138	  int timeout;
1139	  int test_len = 64;
1140	  int ret = 0;
1141	
1142	  /* STEP 0: Pre-flight checks */
1143	
1144	  if (!priv->link_up)
1145	    {
1146	      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
1147	      return -ENETDOWN;
1148	    }
1149	
1150	  if (desc->des0 & DESC_OWN)
1151	    {
1152	      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
1153	      return -EBUSY;
1154	    }
1155	
1156	  syslog(LOG_INFO,
1157	         "=== sg2000_eth TX hardware test ===\n"
1158	         "  tx_desc[%u]=%p  tx_buf=%p  test_len=%d\n",
1159	         idx, desc, priv->tx_buf[idx], test_len);
1160	
1161	  /* STEP 1: Build a minimal broadcast ARP frame.
1162	   * dst=ff:ff:ff:ff:ff:ff  src=our MAC  type=0x0806  payload=0xAA
1163	   */
1164	
1165	  memset(priv->tx_buf[idx], 0, test_len);
1166	  memset(priv->tx_buf[idx], 0xff, 6);
1167	  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);
1168	  priv->tx_buf[idx][12] = 0x08;
1169	  priv->tx_buf[idx][13] = 0x06;
1170	  memset(priv->tx_buf[idx] + 14, 0xaa, test_len - 14);
1171	
1172	  /* STEP 2: Snapshot hardware state before submission */
1173	
1174	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
1175	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1176	
1177	  syslog(LOG_INFO,
1178	         "tx_test: BEFORE doorbell\n"
1179	         "  desc des0=0x%08" PRIX32 " des2=0x%08" PRIX32 "\n"
1180	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1181	         " TX_FSM=%u\n",
1182	         desc->des0, desc->des2, csr5_before, csr6,
1183	         (csr5_before >> 20) & 0x7);
1184	
1185	  /* STEP 3: Program TX descriptor.
1186	   *   des2 = buffer physical address
1187	   *   des1 = len | FS | LS | IC (preserve TER)
1188	   *   des0 = OWN (hand to DMA)
1189	   */
1190	
1191	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1192	  desc->des1 = (uint32_t)test_len | TX_DESC_FS | TX_DESC_LS |
1193	               TX_DESC_IC | (desc->des1 & TX_DESC_TER);
1194	  desc->des0 = DESC_OWN;
1195	
1196	  /* STEP 4: Flush D-cache to DDR.
1197	   *   DMA reads from DDR, not from CPU cache.
1198	   *   Without this, DMA sees stale descriptor values.
1199	   */
1200	
1201	  up_clean_dcache((uintptr_t)priv->tx_buf[idx],
1202	                  (uintptr_t)priv->tx_buf[idx] + test_len);
1203	  up_clean_dcache((uintptr_t)desc,
1204	                  (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1205	  __asm__ volatile ("fence ow,ow" ::: "memory");
1206	
1207	  syslog(LOG_INFO, "tx_test: D-cache flushed, ringing TX doorbell...\n");
1208	
1209	  /* STEP 5: Ring TX doorbell */
1210	
1211	  tx_doorbell(priv);
1212	
1213	  /* STEP 6: Wait for TX completion.
1214	   *   Poll until DMA clears OWN AND TI bit is set, or timeout.
1215	   */
1216	
1217	  timeout = 50000;
1218	
1219	  while (--timeout > 0)
1220	    {
1221	      csr5_after = getreg32(priv->gmac_base + DMA_STATUS);
1222	
1223	      if (!(desc->des0 & DESC_OWN) && (csr5_after & DMA_STATUS_TI))
1224	        {
1225	          break;
1226	        }
1227	
1228	      up_udelay(10);
1229	    }
1230	
1231	  syslog(LOG_INFO,
1232	         "tx_test: waited %d us  timeout=%s\n"
1233	         "  CSR5=0x%08" PRIX32 " TI=%s\n",
1234	         (50000 - timeout) * 10,
1235	         timeout > 0 ? "no" : "YES",
1236	         csr5_after,
1237	         (csr5_after & DMA_STATUS_TI) ? "SET" : "clear");
1238	
1239	  /* STEP 7: Verify layer by layer */
1240	
1241	  /* Layer 1: Did DMA fetch the descriptor?
1242	   *   DMA sees OWN=1 → claims it → clears OWN when done.
1243	   *   OWN still set → DMA never saw it (cache problem or DMA stopped).
1244	   */
1245	
1246	  if (desc->des0 & DESC_OWN)
1247	    {
1248	      syslog(LOG_ERR,
1249	             "*** FAIL [L1]: OWN still set — DMA did NOT fetch "
1250	             "descriptor!\n"
1251	             "  DMA reads from DDR; descriptor stuck in D-cache.\n"
1252	             "  CSR5=0x%08" PRIX32 " TX_FSM=%u\n",
1253	             csr5_after, (csr5_after >> 20) & 0x7);
1254	      ret = -ETIMEDOUT;
1255	      goto out;
1256	    }
1257	
1258	  syslog(LOG_INFO, "  [L1 PASS] DMA fetched descriptor (OWN cleared)\n");
1259	
1260	  /* Layer 2: Did DMA read the data correctly?
1261	   *   Underflow = DMA couldn't read data fast enough (stale cache).
1262	   *   Error Summary in des0 = any TX error occurred.
1263	   */
1264	
1265	  if (csr5_after & DMA_STATUS_UNF)
1266	    {
1267	      syslog(LOG_ERR,
1268	             "*** FAIL [L2]: TX Underflow — DMA could not read "
1269	             "buffer data!\n  CSR5=0x%08" PRIX32 "\n", csr5_after);
1270	      ret = -EIO;
1271	      goto out;
1272	    }
1273	
1274	  if (desc->des0 & TX_DESC_ES)
1275	    {
1276	      syslog(LOG_ERR,
1277	             "*** FAIL [L2]: TX Error Summary in des0=0x%08"
1278	             PRIX32 "\n", desc->des0);
1279	      ret = -EIO;
1280	      goto out;
1281	    }
1282	
1283	  syslog(LOG_INFO, "  [L2 PASS] No Underflow/Error — data read OK\n");
1284	
1285	  /* Layer 3: Did TX Complete interrupt fire?
1286	   *   IC bit was set in des1 → MAC should raise TI in CSR5.
1287	   */
1288	
1289	  if (!(csr5_after & DMA_STATUS_TI))
1290	    {
1291	      syslog(LOG_ERR,
1292	             "*** FAIL [L3]: TI not set — TX Complete interrupt "
1293	             "did NOT fire!\n  Check CSR7 / GMAC_INT_MASK.\n");
1294	      ret = -EIO;
1295	      goto out;
1296	    }
1297	
1298	  syslog(LOG_INFO, "  [L3 PASS] TX Complete interrupt (TI) fired\n");
1299	
1300	  syslog(LOG_INFO,
1301	         "=== TX TEST PASSED ===  total ~%d us\n",
1302	         (50000 - timeout) * 10);
1303	
1304	out:
1305	  /* Advance tx_cur (mirror hw_transmit behavior) */
1306	
1307	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1308	
1309	  /* Clear TI so it doesn't interfere with normal ISR */
1310	
1311	  if (csr5_after & DMA_STATUS_TI)
1312	    {
1313	      putreg32(DMA_STATUS_TI, priv->gmac_base + DMA_STATUS);
1314	    }
1315	
1316	  return ret;
1317	}
1318	
1319	/****************************************************************************
1320	 * Name: netdriver_ifup
1321	 *
1322	 * Description:
1323	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1324	 *
1325	 ****************************************************************************/
1326	
1327	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1328	{
1329	  FAR struct sg2000_eth_priv_s *priv =
1330	      (FAR struct sg2000_eth_priv_s *)dev;
1331	  int ret;
1332	
1333	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1334	
1335	  /* Ensure GMAC clocks and resets are configured */
1336	
1337	  gmac_clock_enable();
1338	
1339	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1340	
1341	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1342	
1343	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1344	  up_mdelay(10);
1345	
1346	  ret = mdio_verify_phy(priv->gmac_base);
1347	  if (ret < 0)
1348	    {
1349	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1350	      return ret;
1351	    }
1352	
1353	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1354	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1355	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1356	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1357	
1358	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1359	
1360	  ret = phy_config_init(priv);
1361	  if (ret < 0)
1362	    {
1363	      nerr("ERROR: PHY init failed: %d\n", ret);
1364	      return ret;
1365	    }
1366	
1367	  ret = dma_soft_reset(priv->gmac_base);
1368	  if (ret < 0)
1369	    {
1370	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1371	             "diagnostics: %d\n", ret);
1372	      return ret;
1373	    }
1374	
1375	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1376	    {
1377	      ret = alloc_dma(priv);
1378	      if (ret < 0)
1379	        {
1380	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1381	          return ret;
1382	        }
1383	    }
1384	
1385	  init_desc_and_dma(priv);
1386	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1387	  start_mac_and_dma(priv);
1388	  rx_doorbell(priv);
1389	
1390	  /* Diagnostic: verify DMA state machines after initialization.
1391	   * TS[22:20]=TX state, RS[19:17]=RX state.  Both should show Running.
1392	   */
1393	
1394	  {
1395	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1396	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1397	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1398	    unsigned int rx_state = (csr5 >> 17) & 0x7;
1399	    static const char * const states[] = {
1400	      "Stopped", "Running(FetchDesc)", "Running(WaitEnd)",
1401	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1402	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1403	    };
1404	
1405	    syslog(LOG_INFO,
1406	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1407	           " CSR6=0x%08" PRIX32 "\n"
1408	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1409	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1410	           csr5, csr6,
1411	           tx_state, states[tx_state],
1412	           rx_state, states[rx_state],
1413	           priv->tx_desc[0].des0, priv->rx_desc[0].des0);
1414	  }
1415	
1416	  up_enable_irq(priv->irq);
1417	  netdev_lower_carrier_on(dev);
1418	
1419	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1420	         priv->speed, priv->duplex ? "Full" : "Half");
1421	
1422	  /* Run minimal HW TX verification before returning to upper half */
1423	
1424	  sg2000_eth_tx_test();
1425	
1426	  return OK;
1427	}
1428	
1429	/****************************************************************************
1430	 * Name: netdriver_ifdown
1431	 *
1432	 * Description:
1433	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1434	 *
1435	 ****************************************************************************/
1436	
1437	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1438	{
1439	  FAR struct sg2000_eth_priv_s *priv =
1440	      (FAR struct sg2000_eth_priv_s *)dev;
1441	  uint32_t v;
1442	
1443	  up_disable_irq(priv->irq);
1444	
1445	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1446	   * Clear ST (bit 13) and SR (bit 1).
1447	   */
1448	
1449	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1450	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1451	           priv->gmac_base + DMA_CONTROL);
1452	
1453	  /* Disable MAC TX/RX */
1454	
1455	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1456	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1457	           priv->gmac_base + GMAC_CONFIG);
1458	
1459	  netdev_lower_carrier_off(dev);
1460	
1461	  ninfo("netdriver_ifdown: interface down\n");
1462	
1463	  return OK;
1464	}
1465	
1466	/****************************************************************************
1467	 * Name: netdriver_transmit
1468	 *
1469	 * Description:
1470	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1471	 *   The driver takes ownership of the netpkt and MUST free it after TX
1472	 *   completion (or on error).
1473	 *
1474	 *   Returned Value:
1475	 *     OK on success (pkt queued for TX); negated errno on failure.
1476	 *
1477	 ****************************************************************************/
1478	
1479	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1480	                               FAR netpkt_t *pkt)
1481	{
1482	  FAR struct sg2000_eth_priv_s *priv =
1483	      (FAR struct sg2000_eth_priv_s *)dev;
1484	  unsigned int len = netpkt_getdatalen(dev, pkt);
1485	  uint8_t *tmp_buf = NULL;
1486	  const uint8_t *data;
1487	  int ret;
1488	
1489	  if (len > SG2000_ETH_BUFSIZE)
1490	    {
1491	      nerr("ERROR: TX packet too large: %u\n", len);
1492	      netpkt_free(dev, pkt, NETPKT_TX);
1493	      return -E2BIG;
1494	    }
1495	
1496	  /* Extract data from netpkt.  If fragmented, copy out to a heap buffer;
1497	   * otherwise use the IOB data pointer directly.
1498	   *
1499	   * A heap buffer is used instead of a stack buffer because
1500	   * SG2000_ETH_BUFSIZE (1600 bytes) risks stack overflow on the
1501	   * netdev thread which has a limited stack size.
1502	   */
1503	
1504	  if (netpkt_is_fragmented(pkt))
1505	    {
1506	      tmp_buf = kmm_malloc(SG2000_ETH_BUFSIZE);
1507	      if (!tmp_buf)
1508	        {
1509	          nerr("ERROR: kmm_malloc(%u) for TX copy buffer failed\n",
1510	               SG2000_ETH_BUFSIZE);
1511	          netpkt_free(dev, pkt, NETPKT_TX);
1512	          return -ENOMEM;
1513	        }
1514	
1515	      syslog(LOG_INFO,
1516	             "sg2000_eth: TX fragmented pkt, len=%u, "
1517	             "copied to heap buf=%p\n", len, tmp_buf);
1518	
1519	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1520	      data = tmp_buf;
1521	    }
1522	  else
1523	    {
1524	      data = netpkt_getdata(dev, pkt);
1525	      if (!data)
1526	        {
1527	          nerr("ERROR: netpkt_getdata returned NULL\n");
1528	          netpkt_free(dev, pkt, NETPKT_TX);
1529	          return -EINVAL;
1530	        }
1531	    }
1532	
1533	  /* Send via DMA */
1534	
1535	  ret = hw_transmit(priv, data, len);
1536	
1537	  /* Free the temporary copy buffer if it was allocated.
1538	   * Safe to free here: hw_transmit() already memcpy'd data into the
1539	   * DMA TX buffer and waited for DMA completion before returning.
1540	   */
1541	
1542	  if (tmp_buf)
1543	    {
1544	      kmm_free(tmp_buf);
1545	    }
1546	
1547	  if (ret < 0)
1548	    {
1549	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1550	      netpkt_free(dev, pkt, NETPKT_TX);
1551	      return ret;
1552	    }
1553	
1554	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1555	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1556	   */
1557	
1558	  {
1559	    irqstate_t flags = up_irq_save();
1560	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1561	
1562	    priv->tx_pkt[slot] = pkt;
1563	    up_irq_restore(flags);
1564	  }
1565	
1566	  return OK;
1567	}
1568	
1569	/****************************************************************************
1570	 * Name: netdriver_receive
1571	 *
1572	 * Description:
1573	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1574	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1575	 *   NULL if no more packets are available.
1576	 *
1577	 *   Returned Value:
1578	 *     A netpkt_t * containing the received packet, or NULL.
1579	 *
1580	 ****************************************************************************/
1581	
1582	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1583	{
1584	  FAR struct sg2000_eth_priv_s *priv =
1585	      (FAR struct sg2000_eth_priv_s *)dev;
1586	  FAR netpkt_t *pkt = NULL;
1587	  struct sg2000_dma_desc_s *desc;
1588	  uint32_t status;
1589	  int frame_len;
1590	  int ret;
1591	
1592	  /* Check if there is a completed RX descriptor */
1593	
1594	  desc = &priv->rx_desc[priv->rx_cur];
1595	  if (desc->des0 & DESC_OWN)
1596	    {
1597	      /* DMA still owns it, no packet ready yet.
1598	       * This can happen if rxready was signaled for a previous packet
1599	       * that was already consumed, or in edge cases.
1600	       */
1601	
1602	      return NULL;
1603	    }
1604	
1605	  status = desc->des0;
1606	
1607	  /* Check for errors */
1608	
1609	  if (status & RX_DESC_ES)
1610	    {
1611	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1612	      goto refill;
1613	    }
1614	
1615	  /* Get frame length.  GMAC_CONFIG_ACS is set, so the hardware
1616	   * already strips the FCS; the length from the descriptor is the
1617	   * actual frame length without CRC.
1618	   */
1619	
1620	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK);
1621	
1622	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1623	    {
1624	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1625	      goto refill;
1626	    }
1627	
1628	  /* Allocate a netpkt for the received data */
1629	
1630	  pkt = netpkt_alloc(dev, NETPKT_RX);
1631	  if (!pkt)
1632	    {
1633	      nerr("ERROR: netpkt_alloc failed\n");
1634	      goto refill;
1635	    }
1636	
1637	  /* Copy data from DMA RX buffer into the netpkt */
1638	
1639	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1640	  if (ret < 0)
1641	    {
1642	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1643	      netpkt_free(dev, pkt, NETPKT_RX);
1644	      goto refill;
1645	    }
1646	
1647	refill:
1648	  /* Return the descriptor to DMA (set OWN=1).
1649	   * Preserve RER (RX End of Ring) bit in des1 if set during init.
1650	   */
1651	
1652	  desc->des0 = DESC_OWN;
1653	  desc->des1 = RX_BUF_SIZE | (desc->des1 & RX_DESC_RER);
1654	
1655	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1656	  rx_doorbell(priv);
1657	
1658	  return pkt;
1659	}
1660	
1661	/****************************************************************************
1662	 * Private Data - Operations Structure
1663	 *
1664	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1665	 ****************************************************************************/
1666	
1667	static const struct netdev_ops_s g_ops =
1668	{
1669	  netdriver_ifup,     /* ifup */
1670	  netdriver_ifdown,   /* ifdown */
1671	  netdriver_transmit, /* transmit */
1672	  netdriver_receive   /* receive */
1673	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1674	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1675	   * filtering scenarios.
1676	   */
1677	};
