1683	/****************************************************************************
1684	 * Name: sg2000_eth_initialize
1685	 *
1686	 * Description:
1687	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1688	 *   network stack as a netdev_lowerhalf_s device.
1689	 *
1690	 *   Called from board_late_initialize() during system bringup.
1691	 *
1692	 ****************************************************************************/
1693	
1694	int sg2000_eth_initialize(void)
1695	{
1696	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1697	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1698	  int ret;
1699	
1700	  if (g_eth_initialized)
1701	    {
1702	      ninfo("SG2000 Ethernet driver already initialized\n");
1703	      return OK;
1704	    }
1705	
1706	  memset(priv, 0, sizeof(*priv));
1707	  priv->gmac_base = SG2000_GMAC_BASE;
1708	  priv->phy_base = SG2000_EPHY_BASE;
1709	  priv->phy_top = SG2000_EPHY_TOP;
1710	
1711	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1712	
1713	  priv->mac_addr[0] = 0x02;
1714	  priv->mac_addr[1] = 0x00;
1715	  priv->mac_addr[2] = 0x00;
1716	  priv->mac_addr[3] = 0x00;
1717	  priv->mac_addr[4] = 0x00;
1718	  priv->mac_addr[5] = 0x01;
1719	
1720	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1721	         IFHWADDRLEN);
1722	
1723	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1724	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1725	  dev->ops              = &g_ops;
1726	
1727	  priv->irq = SG2000_IRQ_GMAC;
1728	
1729	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1730	  if (ret < 0)
1731	    {
1732	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1733	      return ret;
1734	    }
1735	
1736	  netdev_lower_carrier_off(dev);
1737	  g_eth_initialized = true;
1738	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1739	
1740	  gmac_clock_enable();
1741	
1742	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1743	  if (ret < 0)
1744	    {
1745	      nerr("ERROR: irq_attach failed: %d\n", ret);
1746	      return OK;
1747	    }
1748	
1749	  up_enable_irq(priv->irq);
1750	  ninfo("IRQ %d enabled\n", priv->irq);
1751	
1752	  return OK;
1753	}
1754	
1755	/****************************************************************************
1756	 * Name: riscv_netinitialize
1757	 *
1758	 * Description:
1759	 *   Arch-level network initialization called from up_initialize().
1760	 *   Initializes the SG2000 Ethernet driver.
1761	 *
1762	 ****************************************************************************/
1763	
1764	void riscv_netinitialize(void)
