/****************************************************************************
 * T-Head C906 D-Cache Management Instructions
 *
 * The C906 core has a non-coherent L1 D-cache.  DMA engines (like the
 * DWMAC1000) read/write directly from DDR, not through the CPU cache.
 * We must explicitly flush (clean) CPU writes to DDR before DMA reads,
 * and invalidate stale cache lines before the CPU reads DMA-written data.
 *
 * These macros encode the C906 custom-0 (opcode 0x0b) instructions.
 * DCACHE.IALL at 0x0020000b is already verified in sg2000_mm_init.c.
 *
 * Use address-range clean (DCACHE.CVA) before DMA operations to avoid
 * touching the entire cache.  For post-DMA invalidation, CIAL (clean +
 * invalidate all) is still used as a safe fallback until the DCACHE.IVA
 * per-line encoding is confirmed.
 ****************************************************************************/

/* C906 L1 D-cache line size */
#define C906_DCACHE_LINE_SIZE     64

/* DCACHE.CALL: Clean (write-back) all L1 D-cache lines to DDR */
#define C906_DCACHE_CALL() \
  do { __asm__ volatile (".long 0x0010000b\n" ::: "memory"); } while (0)

/* DCACHE.IALL: Invalidate all L1 D-cache lines (CAUTION: loses dirty data) */
#define C906_DCACHE_IALL() \
  do { __asm__ volatile (".long 0x0020000b\n" ::: "memory"); } while (0)

/* DCACHE.CIAL: Clean + Invalidate all L1 D-cache lines (safe) */
#define C906_DCACHE_CIAL() \
  do { __asm__ volatile (".long 0x0030000b\n" ::: "memory"); } while (0)

/* SYNC.S: Ensure all cache operations are completed */
#define C906_SYNC_S() \
  do { __asm__ volatile (".long 0x0190000b\n" ::: "memory"); } while (0)

/* DMA fence: ensure memory writes are globally visible before
 * device register writes (doorbell).  fence w,o = predecessor
 * writes (all memory) ordered before successor writes (device I/O).
 */
#define C906_DMA_FENCE() \
  do { __asm__ volatile ("fence w,o" ::: "memory"); } while (0)

/****************************************************************************
 * Name: c906_clean_dcache_line
 *
 * Description:
 *   Clean (write-back) one D-cache line containing the virtual address
 *   to DDR.  Uses the T-Head C906 DCACHE.CVA instruction.
 *   The address is passed via the a0 (x10) register as required by the
 *   0x02a5000b encoding.
 *
 ****************************************************************************/

static inline void c906_clean_dcache_line(uintptr_t addr)
{
  register uintptr_t a0 asm("a0") = addr;

  __asm__ volatile (".long 0x02a5000b\n" : : "r"(a0) : "memory");
}

/****************************************************************************
 * Name: c906_clean_dcache_range
 *
 * Description:
 *   Clean (write-back) all D-cache lines overlapping the address range
 *   [start, end) to DDR.  Iterates cache-line by cache-line.
 *
 ****************************************************************************/

static inline void c906_clean_dcache_range(uintptr_t start, uintptr_t end)
{
  uintptr_t addr = start & ~(C906_DCACHE_LINE_SIZE - 1);

  while (addr < end)
    {
      c906_clean_dcache_line(addr);
      addr += C906_DCACHE_LINE_SIZE;
    }
}

/****************************************************************************
 * Name: c906_dma_flush_before_tx
 *
 * Description:
 *   Flush data buffer + descriptor cache lines to DDR, synchronise, and
 *   insert a memory→device ordering fence.  Call immediately before the
 *   TX doorbell write.
 *
 ****************************************************************************/

static inline void c906_dma_flush_before_tx(uintptr_t buf, int buf_len,
                                             uintptr_t desc, int desc_len)
{
  c906_clean_dcache_range(buf, buf + buf_len);
  c906_clean_dcache_range(desc, desc + desc_len);
  C906_SYNC_S();
  C906_DMA_FENCE();
}

