                                " %02x", priv->tx_buf[idx][i + j]);
                ascii[j] = (priv->tx_buf[idx][i + j] >= 32 &&
                           priv->tx_buf[idx][i + j] < 127)
                           ? priv->tx_buf[idx][i + j] : '.';
              }
            else
              {
                row += snprintf(hex + row, sizeof(hex) - row, "   ");
                ascii[j] = ' ';
              }
          }

        ascii[16] = '\0';
        syslog(LOG_INFO, "%s  |%s|\n", hex, ascii);
      }
  }

  /* Diagnostic: dump TX descriptor and DMA state before doorbell */

  syslog(LOG_INFO,
         "sg2000_eth: TX idx=%u len=%d\n"
         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
         idx, len,
         desc->des0, desc->des1, desc->des2, desc->des3,
         csr5_before, csr6,
         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
         data[0], data[1], data[2], data[3], data[4], data[5],
         data[6], data[7], data[8], data[9], data[10], data[11],
         data[12], data[13]);

  /* Advance tx_cur so tx_cleanup (called from ISR on TX completion)
   * can find this packet.  Packet is tracked in tx_pkt[idx] by the
   * caller BEFORE this function is called, so the ISR can safely
   * free it even if TX completes immediately.
   */

  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  /* Flush D-cache to DDR so DMA can see the descriptor and buffer.
   * Only clean the specific cache lines we touched (buffer + descriptor),
   * NOT the entire D-cache.  This avoids disturbing other kernel state.
