static void tx_cleanup(struct sg2000_eth_priv_s *priv)
{
  /* Called from ISR context.  Only advance tx_dirty and increment the
   * completion counter — do NOT free netpkts or call netdev_lower_txdone.
   * Those heap operations must happen in thread context (process_tx_deferred)
   * to avoid corrupting the heap when an ISR interrupts an ongoing malloc/free.
   */

  while (priv->tx_dirty != priv->tx_cur)
    {
      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];

      /* Invalidate D-cache to see DMA's write-back (OWN cleared) */

      C906_DCACHE_CIAL();
      C906_SYNC_S();

      if (desc->des0 & DESC_OWN)
        {
          break;
        }

      /* DMA completed this slot — count it but defer the free.
       * The tx_pkt[] pointer is still valid; process_tx_deferred()
       * will free it from thread context.
       */

      priv->tx_complete_count++;
      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
    }
}

/****************************************************************************
 * Name: process_tx_deferred
 *
 * Description:
 *   Free completed TX packets from thread context.  tx_cleanup (ISR)
 *   advances tx_dirty; this function catches up from tx_free_idx to
 *   tx_dirty and performs the actual netpkt_free + netdev_lower_txdone.
 *   Must ONLY be called from thread context — never from ISR.
 *
 ****************************************************************************/

static void process_tx_deferred(struct sg2000_eth_priv_s *priv)
{
  while (priv->tx_free_idx != priv->tx_dirty)
    {
      if (priv->tx_pkt[priv->tx_free_idx] != NULL)
        {
          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_free_idx],
                      NETPKT_TX);
          priv->tx_pkt[priv->tx_free_idx] = NULL;

          /* Notify upper half that TX is done */

          netdev_lower_txdone(&priv->dev);
        }

      priv->tx_free_idx = (priv->tx_free_idx + 1) &
                          (TX_RING_SIZE - 1);
    }
}

